antiPatterns.code:
// Avoid: Showing trivial tool calls
<ToolCall toolCall={{ name: 'echo', arguments: { text: 'hello' }, status: 'completed' }} />

// Prefer: Only show meaningful tool usage
<ToolCall toolCall={{ name: 'search_database', arguments: { query: complexQuery }, status: 'completed' }} />

// Avoid: Including sensitive data
<ToolCall toolCall={{ 
  name: 'api_call', 
  arguments: { apiKey: 'secret-key' }, 
  status: 'completed' 
}} />

// Prefer: Redact sensitive information
<ToolCall toolCall={{ 
  name: 'api_call', 
  arguments: { apiKey: '[REDACTED]' }, 
  status: 'completed' 
}} />

// Avoid: Not addressing failures
<ToolCall toolCall={{ name: 'save', status: 'failed' }} />

// Prefer: Handle and display failures appropriately
<ToolCall toolCall={{ name: 'save', status: 'failed', result: { error: 'Permission denied' } }} />
